B.a0k=new A.hO("\uc5b4\ub5a4 \uc77c\uc0c1\uc5d0 \uc4f8 \ucc28\uc778\uc9c0 \uc815\ud574\uc694","\ucd9c\ud1f4\uadfc \uac70\ub9ac, \uc8fc\ub85c \ud0c0\ub294 \uc778\uc6d0, \uc8fc\ucc28 \ud658\uacbd\ubd80\ud130 \uc0dd\uac01\ud574 \ubcf4\uc138\uc694. \ucc28 \ud06c\uae30\uc640 \uc5f0\uac04 \uc8fc\ud589\uac70\ub9ac\ub97c \uc815\ud55c \ub4a4 \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \uc6d4 \uc608\uc0b0\uc744 \uc7a1\uc73c\uba74 \uc120\ud0dd \ubc94\uc704\ub97c \uc904\uc77c \uc218 \uc788\uc5b4\uc694.","\uccab\ucc28! \uc608\uc05c \uac83\ub3c4 \uc88b\uc9c0\ub9cc \ub0b4 \uc77c\uc0c1\uc5d0 \ub9de\uc544\uc57c\uaca0\uc9c0?","\ucd9c\ud1f4\uadfc \uac70\ub9ac, \ud0d1\uc2b9 \uc778\uc6d0, \uc8fc\ucc28 \ud658\uacbd\ubd80\ud130 \uc0dd\uac01\ud574 \ubcf4\uc138\uc694.")
B.a0f=new A.hO("\uc120\ub0a9\uae08\uacfc \ubcf4\uc99d\uae08\uc740 \ub2e4\ub978 \ub3c8\uc774\uc5d0\uc694","\uc120\ub0a9\uae08\uc740 \ub300\uc5ec\ub8cc \uc77c\ubd80\ub97c \ubbf8\ub9ac \ub0b4\ub294 \ub3c8\uc73c\ub85c, \ub9cc\uae30\uc5d0 \ub3cc\ub824\ubc1b\ub294 \ubcf4\uc99d\uae08\uacfc \ub2ec\ub77c\uc694. \uc120\ub0a9\uae08 0\uc6d0 \uc870\uac74\uc774 \uc788\uc5b4\ub3c4 \uc2ec\uc0ac\uc5d0 \ub530\ub77c \ubcf4\uc99d\uae08 \ub4f1\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694. \uc6d4 \ub0a9\uc785\ub8cc\uc5d0 \uc8fc\uc720\xb7\ucda9\uc804\ube44, \uc8fc\ucc28\ube44, \ud1b5\ud589\ub8cc\ub3c4 \ub354\ud574 \uc608\uc0b0\uc744 \ubcf4\uc138\uc694.","\ucc98\uc74c \ub0bc \ub3c8\uacfc \ub9e4\ub2ec \uc4f8 \ub3c8\uc744 \ub098\ub220 \uc801\uc5b4\ubcf4\uc790.","\uc120\ub0a9\uae08 0\uc6d0 \uc870\uac74\uc774\uc5b4\ub3c4 \uc2ec\uc0ac\uc5d0 \ub530\ub77c \ubcf4\uc99d\uae08 \ub4f1\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694.")
B.a0c=new A.hO("\ubcf4\ud5d8\uc774 \ud3ec\ud568\ub3fc\ub3c4 \ud655\uc778\ud560 \uac83\uc774 \uc788\uc5b4\uc694","\uc7a5\uae30\ub80c\ud2b8\ub294 \ubcf4\ud1b5 \ub80c\ud130\uce74 \ud68c\uc0ac \ubcf4\ud5d8\uc73c\ub85c \uc0ac\uace0\ub97c \ucc98\ub9ac\ud574\uc694. \uadf8\ub807\ub2e4\uace0 \uc0ac\uace0 \ube44\uc6a9\uc774 \ud56d\uc0c1 0\uc6d0\uc778 \uac83\uc740 \uc544\ub2c8\uc5d0\uc694. \uc6b4\uc804\uc790 \ub098\uc774\xb7\ubc94\uc704, \ubcf4\uc7a5 \ud55c\ub3c4, \uc790\uae30\ubd80\ub2f4\uae08\uacfc \ubcf4\uc0c1 \uc81c\uc678 \uc870\uac74\uc744 \ud655\uc778\ud558\uc138\uc694. \ub9ac\uc2a4\ub294 \ubcc4\ub3c4 \uac00\uc785\ud560 \ubcf4\ud5d8\ub8cc\ub3c4 \ud568\uaed8 \uacc4\uc0b0\ud574\uc694.","\ubcf4\ud5d8 \ud3ec\ud568\uc774\ub77c\uace0 \ub05d\uc774 \uc544\ub2c8\ub124. \uc790\uae30\ubd80\ub2f4\uae08\ub3c4 \ubb3c\uc5b4\ubcf4\uc790.","\uc6b4\uc804\uc790 \uc870\uac74\xb7\ubcf4\uc7a5 \ubc94\uc704\xb7\uc790\uae30\ubd80\ub2f4\uae08\uc740 \uacc4\uc57d\ub9c8\ub2e4 \ub2ec\ub77c\uc694.")
B.a0j=new A.hO("\uacc4\uc57d \ub05d\ub0a0 \ub54c\uc758 \uc120\ud0dd\uae4c\uc9c0 \uc0b4\ud3b4\ubd10\uc694","\uc608\uc0c1 \uc8fc\ud589\uac70\ub9ac\uc640 \uc774\uc6a9 \uae30\uac04\uc744 \ubb34\ub9ac \uc5c6\uc774 \uc815\ud558\uc138\uc694. \uc57d\uc815 \uac70\ub9ac\ub97c \ub118\uae30\uac70\ub098 \uc911\ub3c4\uc5d0 \uacc4\uc57d\uc744 \ub05d\ub0b4\uba74 \ube44\uc6a9\uc774 \uc0dd\uae38 \uc218 \uc788\uc5b4\uc694. \ub9cc\uae30 \uc778\uc218\xb7\ubc18\ub0a9 \uac00\ub2a5 \uc5ec\ubd80\uc640 \uac01\uac01\uc758 \uc815\uc0b0 \ud56d\ubaa9\ub3c4 \uacc4\uc57d \uc804\uc5d0 \ud655\uc778\ud574 \ub450\uc138\uc694.","\uc5bc\ub9c8\ub098 \ud0c0\uace0, \uc5b8\uc81c\uae4c\uc9c0 \uc4f8\uc9c0 \uc815\ud55c \ub4a4 \uc120\ud0dd\ud560\ub798.","\ucd08\uacfc \uc8fc\ud589\uac70\ub9ac, \uc911\ub3c4\ud574\uc9c0, \ub9cc\uae30 \uc120\ud0dd \uc870\uac74\ub3c4 \ubbf8\ub9ac \ud655\uc778\ud574\uc694.")
B.a70=s([B.a0k,B.a0f,B.a0c,B.a0j],t.ca)
B.a0n=new A.yv("first_car","\uccab\ucc28 \uac00\uc774\ub4dc","\uccab\ucc28\ub77c\uba74 \uc774\uac83\ub9cc \uc54c\uba74 \ub3fc\uc694","\ucc28\ub97c \uace0\ub974\uae30 \uc804\uc5d0 \ub0b4 \uc608\uc0b0\uacfc \uc774\uc6a9 \uc870\uac74\ubd80\ud130 \uc815\ud558\uba74 \ud6e8\uc52c \uc26c\uc6cc\uc838\uc694.",B.a9h,B.a70,"\uc120\ub0a9\uae08 0\uc6d0\uc740 \ub204\uad6c\ub098 \ubb34\uc870\uac74 \uac00\ub2a5\ud55c \uc870\uac74\uc774 \uc544\ub2c8\uc5d0\uc694. \uc2ec\uc0ac \uacb0\uacfc\uc640 \uacc4\uc57d \uc0c1\ud488\uc5d0 \ub530\ub77c \ucd08\uae30 \ube44\uc6a9\xb7\ubcf4\ud5d8 \uc870\uac74\xb7\ucd5c\uc885 \ub0a9\uc785\ub8cc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5b4\uc694.")
B.ahl=new A.iZ("\ucc28\ub7c9 \uc0c1\ud0dc \xb7 \ucd08\uacfc \uc8fc\ud589\uac70\ub9ac \ub4f1 \uc815\uc0b0 \ud655\uc778","\ubc18\ub0a9")
B.ahC=new A.iZ("\uc778\uc218\uac00 + \uc138\uae08\xb7\uc774\uc804 \ube44\uc6a9\uae4c\uc9c0 \ud655\uc778","\uc778\uc218")
